import {parseVariantTransferFiles,variantArchiveCandidate} from '../../src/domain/variant-transfer.ts';
import {Reports} from '../../src/features/reports.ts';import {Repository} from '../../src/domain/repository.ts';import {appendCustomVariant} from '../../src/domain/variant-edits.ts';
import {defaultReportSettings} from '../../src/domain/reports.ts';import {recordBlank} from '../../src/domain/model.ts';import catalog from '../../src/data/catalog.json';import variants from '../../src/data/report-variants.json';import type {Experiment} from '../../src/domain/types.ts';
export async function createReportVariantFixture(){const exp=catalog.experiments[0] as Experiment,doc=recordBlank(exp),profile={name:'',studentId:'',className:''},data=new Map<string,string>();let archiveFailure=false;const notices:string[]=[];const repo=new Repository({read:async k=>data.get(k)??null,write:async(k,v)=>{if(archiveFailure&&k.startsWith('variant-'))throw Error('模拟归档失败');data.set(k,v)},remove:async k=>{data.delete(k)}}),section=Object.entries((variants as Record<string,Record<string,unknown>>)[exp.id]).find(([,v])=>Array.isArray(v))![0];await repo.saveReportSettings(exp.id,{...defaultReportSettings(),ai:{source:JSON.stringify({draft:doc.draft,date:doc.date}),polish:{[section]:'旧润色',另章:'保留内容'},customQuiz:{questions:['保留问题'],answers:{1:['保留答案']}}}});let asks=0;const report=new Reports(repo,{context:()=>({exp,doc,profile,photo:null,blocked:false}),flush:async()=>{},notice:message=>{notices.push(message)},jump:()=>{},confirm:async()=>true,configureAI:()=>{},upload:()=>{}},{status:async()=>({hasKey:true}),skills:async()=>[],knowledge:async sourceId=>({sourceId,text:'原理知识'}),complete:async(_slot,messages)=>{asks++;return {text:'模拟变体标记。'+String(messages[1].content).split('原文：')[1],elapsedMs:1};}});await report.open();const appendFromLibrary=async()=>{const summary=(await repo.listVariantLibrary(exp.id))[0],entry=await repo.readVariantArchive(exp.id,summary.id),current=await repo.loadReportSettings(exp.id);await repo.saveReportSettings(exp.id,appendCustomVariant(current,(variants as Record<string,Record<string,unknown>>)[exp.id],entry.section,{id:entry.id,baseIndex:entry.index,original:entry.original,text:entry.text}));report.close();await report.open();};return {appendStandalone:async()=>{const [entry]=await parseVariantTransferFiles([{name:'自建变体_'+exp.sourceId+'.json',text:JSON.stringify({[section]:['独立原文 $s_{mobile}=1$']})}],{experiments:catalog.experiments,templates:variants});await repo.archiveVariant(entry);const base=(variants as Record<string,Record<string,unknown>>)[exp.id];await repo.saveReportSettings(exp.id,appendCustomVariant(await repo.loadReportSettings(exp.id),base,entry.section,variantArchiveCandidate(entry,base)));report.close();await report.open();},latestArchive:async()=>{const first=(await repo.listVariantLibrary(exp.id))[0];return repo.readVariantArchive(exp.id,first.id);},appendFromLibrary,stale:async()=>{await appendFromLibrary();const current=await repo.loadReportSettings(exp.id);current.customVariants![section][0].baseCount++;await repo.saveReportSettings(exp.id,current);report.close();await report.open();},archiveFailure:(v:boolean)=>archiveFailure=v,library:()=>repo.listVariantLibrary(exp.id),state:()=>({asks,section,notices,open:report.isOpen,saving:report.isSaving}),settings:()=>repo.loadReportSettings(exp.id),back:()=>report.closeTopPreview()};}
